private struct VehicleImage: View {
    var urlString: String? = nil
    var vehicle: NinebotVehicleInfo? = nil
    var size: CGFloat
    var showsBackground = true
    @Environment(\.colorScheme) private var colorScheme

    var body: some View {
        ZStack {
            if showsBackground {
                RoundedRectangle(cornerRadius: 18, style: .continuous)
                    .fill(Color(.tertiarySystemGroupedBackground))
            }

            if let urlString = effectiveURLString, let url = URL(string: urlString) {
                AsyncImage(url: url) { phase in
                    switch phase {
                    case .success(let image):
                        image
                            .resizable()
                            .scaledToFit()
                            .padding(6)
                    case .failure:
                        fallbackImage
                    case .empty:
                        ProgressView()
                            .controlSize(.small)
                    @unknown default:
                        fallbackImage
                    }
                }
            } else {
                fallbackImage
            }
        }
        .frame(width: size, height: size)
    }

    private var effectiveURLString: String? {
        vehicle?.imageURLString(prefersDarkImage: colorScheme == .dark) ?? urlString
    }

    private var fallbackImage: some View {
        Image(systemName: "bolt.car.fill")
            .font(.system(size: size * 0.38, weight: .semibold))
            .foregroundStyle(.secondary)
    }
}

